// ps/io/chassis_hull_io.h — JSON loading for a chassis collision hull (physics_sim.chassis_hull/1,
// docs/data_formats/chassis_hull.md, generated by tools/collisiongen/chassis_hull.py). nlohmann::json stays
// confined to chassis_hull_io.cpp.

#pragma once

#include "ps/backend/shape_desc.h"

#include <string>

namespace ps::io {

// Loads data/collision/*_hull.json into a ConvexCompoundShape in chassis body coordinates. Throws
// std::runtime_error on an unreadable/malformed file, a missing/wrong "format", no pieces, a piece with fewer than
// 4 points, a non-finite coordinate, a negative convex_radius_m or a missing "source".
ConvexCompoundShape load_chassis_hull_json(const std::string& path);

} // namespace ps::io
